/// Relay server: multi-endpoint accept loops (spec §9).
///
/// Supported protocols:
///   proto="ws"    → plain WebSocket (JSON frames)
///   proto="wss"   → WebSocket over TLS
///   proto="http"  → plain HTTP/1.1 POST handler
///   proto="https" → HTTP/1.1 POST over TLS
///
/// `wss` and `https` require the endpoint's `tls` field to carry a pre-built
/// `TlsAcceptor` (with a self-signed cert generated by `transport::tls`).
///
/// The pool uses interior locking but handlers run on a single-threaded
/// `LocalSet` executor.
use std::future::Future;
use std::net::SocketAddr;
use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
use std::sync::Arc;

use anyhow::{Context, Result};
use futures_util::{SinkExt, StreamExt};
use tokio::io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt};
use tokio::net::TcpListener;
use tokio::task::{spawn_local, LocalSet};
use tokio_tungstenite::accept_async;
use tokio_tungstenite::tungstenite::Message;

/// Combined trait for erased stream type.
/// Both `TcpStream` and `TlsStream<TcpStream>` implement this.
trait AnyStream: AsyncRead + AsyncWrite + Unpin + Send {}
impl<T: AsyncRead + AsyncWrite + Unpin + Send> AnyStream for T {}

/// Boxed erased stream for the accept loop handler.
type BoxedStream = Box<dyn AnyStream>;

use crate::pool::Pool;
use crate::requests::batch::{try_batch_or_direct, BatchProcessor};
use crate::types::{LocalNode, LocalRoom};

// ══════════════════════════════════════════════════════════════════════
// Public types
// ══════════════════════════════════════════════════════════════════════

/// Live connection counters for a running relay instance.
pub struct RelayMetrics {
    pub active: AtomicUsize,
    pub total: AtomicUsize,
    pub bytes_in: AtomicU64,
    pub bytes_out: AtomicU64,
}

impl RelayMetrics {
    pub fn new() -> Self {
        Self {
            active: AtomicUsize::new(0),
            total: AtomicUsize::new(0),
            bytes_in: AtomicU64::new(0),
            bytes_out: AtomicU64::new(0),
        }
    }
}

impl Default for RelayMetrics {
    fn default() -> Self {
        Self::new()
    }
}

/// One transport endpoint that this relay should listen on.
pub struct EndpointConfig {
    /// Socket address to bind on (e.g. `0.0.0.0:17701`).
    pub addr: SocketAddr,
    /// Transport protocol: `"ws"`, `"wss"`, `"http"`, `"https"`.
    pub proto: String,
    /// URL path for HTTP/HTTPS endpoints (default `/`).
    pub path: Option<String>,
    /// Pre-built TLS acceptor — required for `wss` and `https`, `None` otherwise.
    #[cfg(feature = "tls")]
    pub tls: Option<Arc<tokio_rustls::TlsAcceptor>>,
    #[cfg(not(feature = "tls"))]
    pub tls: Option<()>,
}

/// Relay configuration passed to [`run_relay`].
pub struct RelayConfig {
    /// Relay's Ed25519 + X25519 identity.
    pub node: LocalNode,
    /// Transport endpoints to listen on.  At least one required.
    pub endpoints: Vec<EndpointConfig>,
    /// Shared event pool.  Not `Sync`; all access happens on the local executor.
    pub pool: Arc<Pool>,
    /// Rooms for which this relay holds the private key (key-holder rooms).
    pub rooms: std::collections::HashMap<String, LocalRoom>,
    /// Optional live metrics counters.
    pub metrics: Option<Arc<RelayMetrics>>,
    /// Optional batch processor for high-throughput request handling.
    pub batch_processor: Option<BatchProcessor>,
}

// ══════════════════════════════════════════════════════════════════════
// Entry point
// ══════════════════════════════════════════════════════════════════════

/// Start the relay server inside a `LocalSet`.
///
/// Spawns one accept loop per endpoint.  Runs indefinitely until the outer
/// future is cancelled (e.g. via `tokio::select!` with a stop channel).
pub async fn run_relay(config: Arc<RelayConfig>) -> Result<()> {
    if config.endpoints.is_empty() {
        anyhow::bail!("RelayConfig has no endpoints");
    }

    let local = LocalSet::new();

    for ep in &config.endpoints {
        let cfg = Arc::clone(&config);
        let addr = ep.addr;
        let proto = ep.proto.clone();
        let path = ep.path.clone().unwrap_or_else(|| "/".to_owned());

        #[cfg(feature = "tls")]
        let tls = ep.tls.clone();

        local.spawn_local(async move {
            let result = match proto.as_str() {
                "ws" => run_accept_loop(addr, "WS".to_owned(), None, cfg, |s, p, c| do_ws_session(s, p, c)).await,
                #[cfg(feature = "tls")]
                "wss" => match tls {
                    Some(t) => run_accept_loop(addr, "WSS".to_owned(), Some(t), cfg, |s, p, c| do_ws_session(s, p, c)).await,
                    None => Err(anyhow::anyhow!("wss endpoint missing TLS acceptor")),
                },
                "http" => run_http_accept_loop(addr, path, None, cfg).await,
                #[cfg(feature = "tls")]
                "https" => match tls {
                    Some(t) => run_http_accept_loop(addr, path, Some(t), cfg).await,
                    None => Err(anyhow::anyhow!("https endpoint missing TLS acceptor")),
                },
                #[cfg(not(feature = "tls"))]
                "wss" | "https" => Err(anyhow::anyhow!("TLS protocols (wss/https) require the 'tls' feature")),
                p => {
                    log_info(format!("endpoint proto={p}: not supported, skipping"));
                    Ok(())
                }
            };
            if let Err(e) = result {
                log_info(format!("endpoint {proto} error: {e}"));
            }
        });
    }

    local
        .run_until(futures_util::future::pending::<Result<()>>())
        .await
}

// ══════════════════════════════════════════════════════════════════════
// Generic accept loop for WS/WSS and HTTP/HTTPS
// ══════════════════════════════════════════════════════════════════════

/// Run a generic accept loop for a protocol (ws/wss/http/https).
///
/// The `handler` closure is called for each accepted connection with the
/// (possibly TLS-wrapped) stream and peer address. It should drive the
/// protocol session to completion.
#[cfg(feature = "tls")]
async fn run_accept_loop<F, Fut>(
    addr: SocketAddr,
    proto: String,
    tls: Option<Arc<tokio_rustls::TlsAcceptor>>,
    config: Arc<RelayConfig>,
    handler: F,
) -> Result<()>
where
    F: Fn(BoxedStream, SocketAddr, Arc<RelayConfig>) -> Fut + 'static + Clone,
    Fut: Future<Output = Result<()>> + 'static,
{
    let listener = TcpListener::bind(addr)
        .await
        .with_context(|| format!("failed to bind {proto} on {addr}"))?;
    log_info(format!("{proto} relay listening on {addr}"));

    loop {
        let (stream, peer_addr) = listener.accept().await.context(format!("{proto} accept"))?;
        let cfg = Arc::clone(&config);
        let proto = proto.clone();
        let handler = handler.clone();

        match &tls {
            None => {
                let stream: BoxedStream = Box::new(stream);
                spawn_local(async move {
                    if let Err(e) = handler(stream, peer_addr, cfg).await {
                        log_info(format!("{proto} error from {peer_addr}: {e}"));
                    }
                });
            }
            Some(tls_acc) => {
                let tls_acc = Arc::clone(tls_acc);
                let handler = handler.clone();
                let proto = proto.clone();
                spawn_local(async move {
                    match tls_acc.accept(stream).await {
                        Ok(tls_stream) => {
                            let stream: BoxedStream = Box::new(tls_stream);
                            if let Err(e) = handler(stream, peer_addr, cfg).await {
                                log_info(format!("{proto} error from {peer_addr}: {e}"));
                            }
                        }
                        Err(e) => log_info(format!("{proto} TLS handshake error from {peer_addr}: {e}")),
                    }
                });
            }
        }
    }
}

#[cfg(not(feature = "tls"))]
async fn run_accept_loop<F, Fut>(
    _addr: SocketAddr,
    _proto: String,
    _tls: Option<()>,
    _config: Arc<RelayConfig>,
    _handler: F,
) -> Result<()>
where
    F: Fn(BoxedStream, SocketAddr, Arc<RelayConfig>) -> Fut + 'static + Clone,
    Fut: Future<Output = Result<()>> + 'static,
{
    anyhow::bail!("TLS support requires the 'tls' feature")
}

/// Drive a WebSocket session over any `AsyncRead + AsyncWrite + Unpin` stream.
/// Used by both plain `ws` and TLS `wss`.
async fn do_ws_session(stream: BoxedStream, _peer_addr: SocketAddr, config: Arc<RelayConfig>) -> Result<()> {
    bump_metrics(&config, true);
    let mut ws = accept_async(stream).await.context("WebSocket upgrade")?;
    let result = async {
        while let Some(msg) = ws.next().await {
            let msg = msg.context("WebSocket read")?;
            match msg {
                Message::Text(text) => {
                    if let Some(m) = &config.metrics {
                        m.bytes_in.fetch_add(text.len() as u64, Ordering::Relaxed);
                    }
                    let responses = dispatch_common(&text, &config).await;
                    for v in responses {
                        if let Some(m) = &config.metrics {
                            m.bytes_out.fetch_add(v.len() as u64, Ordering::Relaxed);
                        }
                        ws.send(Message::Binary(v.into()))
                            .await
                            .context("WS send")?;
                    }
                    // Signal end of response batch so clients can proceed.
                    ws.send(Message::Binary(r#"{"done":true}"#.as_bytes().to_vec().into()))
                        .await
                        .context("WS done")?;
                }
                Message::Binary(_) => {}
                Message::Close(_) => break,
                Message::Ping(p) => {
                    ws.send(Message::Pong(p)).await.context("WS pong")?;
                }
                _ => {}
            }
        }
        Ok(())
    }.await;
    bump_metrics(&config, false);
    result
}

// ══════════════════════════════════════════════════════════════════════
// HTTP / HTTPS — single request / response per connection (Connection: close)
// ══════════════════════════════════════════════════════════════════════
//
// Accepts POST <path> HTTP/1.1 with a JSON envelope body.
// Returns a JSON array of response envelopes.
// Plain HTTP uses a raw TcpStream; HTTPS wraps it with a TlsStream first.

#[cfg(feature = "tls")]
async fn run_http_accept_loop(
    addr: SocketAddr,
    path: String,
    tls: Option<Arc<tokio_rustls::TlsAcceptor>>,
    config: Arc<RelayConfig>,
) -> Result<()> {
    let proto = if tls.is_some() { "HTTPS" } else { "HTTP" };
    let full_proto = format!("{} (path={})", proto, path);

    run_accept_loop(addr, full_proto, tls, config, move |stream: BoxedStream, peer, cfg| {
        let path = path.clone();
        async move { do_http_connection(stream, peer, cfg, &path).await }
    }).await
}

#[cfg(not(feature = "tls"))]
async fn run_http_accept_loop(
    addr: SocketAddr,
    path: String,
    _tls: Option<()>,
    config: Arc<RelayConfig>,
) -> Result<()> {
    // Only HTTP (no TLS) when tls feature is disabled
    run_accept_loop(addr, format!("HTTP (path={})", path), None, config, move |stream: BoxedStream, peer, cfg| {
        let path = path.clone();
        async move { do_http_connection(stream, peer, cfg, &path).await }
    }).await
}

/// Minimal HTTP/1.1 server handling a single POST request, then closing.
/// Works over any `AsyncRead + AsyncWrite + Unpin` (TcpStream or TlsStream).
async fn do_http_connection(
    mut stream: BoxedStream,
    _peer: SocketAddr,
    config: Arc<RelayConfig>,
    want_path: &str,
) -> Result<()>
{
    // Read headers byte-by-byte until the blank line (\r\n\r\n).
    let mut header_buf: Vec<u8> = Vec::with_capacity(2048);
    loop {
        let mut byte = [0u8; 1];
        match stream.read(&mut byte).await {
            Ok(0) => return Ok(()), // client closed before sending headers
            Ok(_) => header_buf.push(byte[0]),
            Err(e) => return Err(e.into()),
        }
        if header_buf.ends_with(b"\r\n\r\n") {
            break;
        }
        if header_buf.len() > 16 * 1024 {
            anyhow::bail!("HTTP headers exceed 16 KiB");
        }
    }

    // Parse request line + headers.
    let header_str = std::str::from_utf8(&header_buf).context("HTTP headers not UTF-8")?;
    let mut lines = header_str.split("\r\n");

    let req_line = lines.next().unwrap_or("");
    let mut parts = req_line.splitn(3, ' ');
    let method = parts.next().unwrap_or("");
    let path = parts.next().unwrap_or("");

    let mut content_length: usize = 0;
    for line in lines {
        let ll = line.to_ascii_lowercase();
        if let Some(rest) = ll.strip_prefix("content-length:") {
            content_length = rest.trim().parse().unwrap_or(0);
        }
    }

    // Only handle POST to the configured path; everything else → 404.
    if method != "POST" || path != want_path {
        let body = b"Not Found\n";
        let resp = format!(
            "HTTP/1.1 404 Not Found\r\n\
             Content-Type: text/plain\r\n\
             Content-Length: {}\r\n\
             Connection: close\r\n\r\n",
            body.len()
        );
        stream.write_all(resp.as_bytes()).await.ok();
        stream.write_all(body).await.ok();
        stream.flush().await.ok();
        return Ok(());
    }

    // Read request body.
    if content_length > 1 << 20 {
        anyhow::bail!("HTTP request body too large: {content_length} bytes");
    }
    let mut body = vec![0u8; content_length];
    stream
        .read_exact(&mut body)
        .await
        .context("HTTP body read")?;

    if let Some(m) = &config.metrics {
        bump_metrics(&config, true);
        m.bytes_in.fetch_add(body.len() as u64, Ordering::Relaxed);
    }

    let json_str = std::str::from_utf8(&body).context("request body not UTF-8")?;
    let responses = dispatch_common(json_str, &config).await;
    // Concatenate response bytes into a JSON array: [env1,env2,...]
    let mut resp_body = Vec::with_capacity(responses.iter().map(|r| r.len()).sum::<usize>() + responses.len() + 2);
    resp_body.push(b'[');
    for (i, r) in responses.iter().enumerate() {
        if i > 0 {
            resp_body.push(b',');
        }
        resp_body.extend_from_slice(r);
    }
    resp_body.push(b']');

    if let Some(m) = &config.metrics {
        m.bytes_out
            .fetch_add(resp_body.len() as u64, Ordering::Relaxed);
        m.active.fetch_sub(1, Ordering::Relaxed);
    }

    let resp_headers = format!(
        "HTTP/1.1 200 OK\r\n\
         Content-Type: application/json\r\n\
         Content-Length: {}\r\n\
         Connection: close\r\n\r\n",
        resp_body.len()
    );
    stream
        .write_all(resp_headers.as_bytes())
        .await
        .context("HTTP write headers")?;
    stream
        .write_all(&resp_body)
        .await
        .context("HTTP write body")?;
    stream.flush().await.context("HTTP flush")?;

    Ok(())
}

// ══════════════════════════════════════════════════════════════════════
// Shared dispatch
// ══════════════════════════════════════════════════════════════════════

async fn dispatch_common(json_str: &str, config: &Arc<RelayConfig>) -> Vec<Vec<u8>> {
    // Zero-copy parse with simd-json (mutable slice required)
    let mut bytes = json_str.as_bytes().to_vec();
    match crate::envelope::parse_envelope_bytes(&mut bytes) {
        Ok(env) => {
            match try_batch_or_direct(
                config.batch_processor.as_ref(),
                env,
                Arc::clone(&config.pool),
                Arc::clone(config),
            )
            .await
            {
                Ok(responses) => responses,
                Err(e) => vec![format!("{{\"error\":\"internal\",\"message\":\"{}\"}}", e).into_bytes()],
            }
        }
        Err(e) => vec![format!("{{\"error\":\"invalid_envelope\",\"message\":\"{}\"}}", e).into_bytes()],
    }
}

// ══════════════════════════════════════════════════════════════════════
// Helpers
// ══════════════════════════════════════════════════════════════════════

/// Increment or decrement active + (on connect) total metrics.
fn bump_metrics(config: &Arc<RelayConfig>, connect: bool) {
    if let Some(m) = &config.metrics {
        if connect {
            m.active.fetch_add(1, Ordering::Relaxed);
            m.total.fetch_add(1, Ordering::Relaxed);
        } else {
            m.active.fetch_sub(1, Ordering::Relaxed);
        }
    }
}

fn log_info(msg: String) {
    eprintln!("[toloo] {msg}");
}
